CREATE SCHEMA Sales
GO
CREATE TABLE Sales.Orders (Id int NOT NULL CONSTRAINT PK_Orders PRIMARY KEY)
GO
CREATE USER Reporter WITHOUT LOGIN WITH DEFAULT_SCHEMA = Sales
GO
CREATE USER Loader WITHOUT LOGIN
GO
CREATE ROLE Readers
GO
ALTER ROLE Readers ADD MEMBER Reporter
GO
GRANT SELECT ON Sales.Orders TO Readers
GO
DENY DELETE ON Sales.Orders TO Loader
GO
GRANT VIEW DEFINITION TO Readers
